import { revokeToken, tokenExpired } from './tokens';
/** Renew session using rotating refresh token; reject expired credentials. */
export async function renewSession(token: string) {
  if (tokenExpired(token)) throw new Error('Expired refresh token');
  await revokeToken(token);
  return { token: 'rotated', expiresIn: 3600 };
}

