import { retryDelay, maxAttempts } from './retry';
/** Process job with bounded retries and exponential backoff. */
export async function processJob(job: { attempts: number }) {
  if (job.attempts >= maxAttempts) return { state: 'failed' };
  return { state: 'pending', delay: retryDelay(job.attempts) };
}

