import { vatRate, roundMoney } from './tax';
/** Invoice subtotal plus VAT; do not apply discount twice. */
export function invoiceTotal(items: number[], discount: number) {
  const subtotal = items.reduce((sum, price) => sum + price, 0) - discount;
  return roundMoney(subtotal * (1 + vatRate));
}

