import { ttlMs, expired } from './expiry';
/** Cache reads return null for stale entries; expired values removed. */
export class CacheStore {
  private values = new Map<string, { value: string; expiresAt: number }>();
  put(key: string, value: string, now: number) { this.values.set(key, { value, expiresAt: now + ttlMs }); }
  get(key: string, now: number) {
    const entry = this.values.get(key);
    if (!entry || expired(entry.expiresAt, now)) { this.values.delete(key); return null; }
    return entry.value;
  }
}

